const readActions=new Set(['health','bootstrap','notificationsUser','userHistory','dailyStats','monthlyStats','adminDashboard','adminEmployees','adminPeople','adminProjects','adminProjectOptions','adminDataAudit','adminShifts','adminAttendance','adminGroups','adminAssignments','adminLeave','adminNotifications','adminReports','adminEmployeeMonthDetail']);const inflight=new Map();
async function api(action,payload={}){if(readActions.has(action)){const k=action+'|'+JSON.stringify(payload||{});if(inflight.has(k))return inflight.get(k);const p=apiRequest(action,payload);inflight.set(k,p);try{return await p}finally{inflight.delete(k)}}return apiRequest(action,payload)}
const API_TIMEOUTS={attendanceNow:15000,recordGps:15000,syncEvents:40000},VERSION_TOLERANT=new Set(['syncEvents','recordGps','logout','health']);
function transientError(m){const e=Error(m);e.transient=true;return e}
