function isDayShift(s){return !!s&&(/ngày|ngay|full day/i.test(String(s.SHIFT_NAME||''))||/^SHIFT0?4$/i.test(String(s.SHIFT_ID||'')))}
function vnDateOffset(date,days){const d=new Date(Date.parse(date+'T12:00:00+07:00')+days*86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
// Local shift pick (same rules as the server: window = start-EARLY_TOL_MIN … end; overnight shifts carry yesterday's work date).
function localShiftPick(){const clock=vietnamClockParts(),m=clock.minute,c=[];S.shifts.filter(s=>String(s.STATUS||'ACTIVE')==='ACTIVE'&&!isDayShift(s)).forEach(s=>{const a=String(s.START_TIME||'').split(':').map(Number),b=String(s.END_TIME||'').split(':').map(Number);if(a.length<2||b.length<2||a.some(Number.isNaN)||b.some(Number.isNaN))return;const st=a[0]*60+a[1],en0=b[0]*60+b[1],en=en0<=st?en0+1440:en0,early=Number(s.EARLY_TOL_MIN||0);[-1,0].forEach(off=>{const ss=st+off*1440,ee=en+off*1440,ws=ss-early,eligible=m>=ws&&m<=ee,future=m<ws;if(off===-1&&!eligible)return;c.push({s,date:off?vnDateOffset(clock.date,-1):clock.date,eligible,future,dist:eligible?Math.abs(m-ss):future?ws-m:m-ee})})});const el=c.filter(x=>x.eligible).sort((x,y)=>x.dist-y.dist);if(el.length)return el[0];const fu=c.filter(x=>x.future).sort((x,y)=>x.dist-y.dist);return fu[0]||null}
function localShiftState(){const p=localShiftPick();if(!p)return{shift:null,eligible:false,action:'CHECKIN',reason:'Chưa có ca SÁNG/CHIỀU/TỐI phù hợp.'};return{shift:Object.assign({},p.s,{SHIFT_WORK_DATE:p.date}),eligible:p.eligible,action:'CHECKIN',reason:p.eligible?'Đang trong khung giờ chấm ca.':'Chưa đến khung giờ chấm ca.'}}
function currentShift(){if(S.attendanceShift)return S.attendanceShift.shift||null;const p=localShiftPick();return p?Object.assign({},p.s,{SHIFT_WORK_DATE:p.date}):null}
function attendanceForShift(id,date=localDate()){const rows=S.attendance.filter(a=>a.WORK_DATE===date&&String(a.SHIFT_ID)===String(id)&&String(a.STATUS)!=='REJECTED'&&String(a.STATE||'')!=='CANCELLED');return rows.slice(-1)[0]||null}
function vietnamClockParts(){return vietnamClockPartsAt(new Date())}
function vietnamClockPartsAt(at){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(at);const o={};parts.forEach(x=>o[x.type]=x.value);return{date:`${o.year}-${o.month}-${o.day}`,minute:Number(o.hour)*60+Number(o.minute)}}
function refreshAttendanceEligibility(shouldRender=true){let state=S.attendanceShift;if(!state){S.attendanceShift=state=localShiftState()}if(!state.shift){if(navigator.onLine)return;const n=localShiftState();if(!n.shift)return;S.attendanceShift=state=n}if(state.action==='CHECKOUT'){state.eligible=true;return}const sh=state.shift;if(isDayShift(sh))return;const before=state.eligible+'|'+state.reason;const clock=vietnamClockParts(),date=String(sh.SHIFT_WORK_DATE||clock.date),startParts=String(sh.START_TIME||'').split(':').map(Number),endParts=String(sh.END_TIME||'').split(':').map(Number);if(startParts.length<2||endParts.length<2||startParts.some(Number.isNaN)||endParts.some(Number.isNaN))return;let start=startParts[0]*60+startParts[1],end=endParts[0]*60+endParts[1];if(end<=start)end+=1440;const dayDelta=Math.round((Date.parse(date+'T00:00:00+07:00')-Date.parse(clock.date+'T00:00:00+07:00'))/86400000);const now=clock.minute-dayDelta*1440;const earliest=start-Number(sh.EARLY_TOL_MIN||0),latest=end;state.eligible=now>=earliest&&now<=latest;state.reason=state.eligible?'Đang trong khung giờ chấm ca.':(now<earliest?'Chưa đến khung giờ chấm ca.':'Đã hết khung giờ vào ca này.');if(now>latest){if(navigator.onLine&&isAttendanceScreen()&&!window._refreshExpiredShift&&Date.now()-lastBootAt>30000){window._refreshExpiredShift=true;bootstrap().then(()=>{if(isAttendanceScreen())renderAttendanceShiftState(screen==='otherAttendance')}).catch(()=>{}).finally(()=>{window._refreshExpiredShift=false})}else if(!navigator.onLine){const n=localShiftState();if(n.shift)S.attendanceShift=state=n}}if(shouldRender&&!attendanceBusy&&isAttendanceScreen()&&before!==state.eligible+'|'+state.reason)renderAttendanceShiftState(screen==='otherAttendance')}
function renderAttendance(isOther=false,refresh=true){const target=isOther?'otherAttendance':'attendance',same=screen===target,prevSel=same?($('projectSelect')?.value||''):'',prevName=same?($('otherProjectName')?.value||''):'';if(!same)projectTouched=false;screen=target;const sh=currentShift();const custom=!!isOther;const projectField=custom?`<div class="field"><label>Tên công trình lẻ</label><input id="otherProjectName" maxlength=160 placeholder="Nhập tên công trình" required></div>`:`<div class="field"><label>Công trình</label><select id="projectSelect">${S.projects.length?S.projects.map(p=>`<option value="${esc(p.PROJECT_ID)}">${esc(p.PROJECT_NAME)}</option>`).join(''):'<option value="">Không có công trình hoạt động</option>'}</select></div>`;const shName=sh?`${sh.SHIFT_NAME}${sh.START_TIME&&sh.END_TIME?' · '+String(sh.START_TIME).slice(0,5)+'–'+String(sh.END_TIME).slice(0,5):''}`:'Chưa có ca hoạt động';page(`<section class="screen wrap"><button class="back" onclick="goBack()">← QUAY LẠI</button><h1 class="screen-title">${custom?'CHẤM CÔNG KHÁC':'CHẤM CÔNG'}</h1><div class="card"><div class="row-head"><b>CA LÀM</b><span class="status-pill ok">${esc(shName)}</span></div>${projectField}<div id="gpsLine" class="gps-line"></div><div id="attendanceActionArea"></div><p class="helper" id="shiftHint">${esc(S.attendanceShift?.reason||'Đang xác định ca làm phù hợp…')}</p></div></section>`);const openAtt=sh&&attendanceForShift(sh.SHIFT_ID,sh.SHIFT_WORK_DATE||localDate()),isOpen=!!(openAtt&&openAtt.CHECKIN_TIME&&!openAtt.CHECKOUT_TIME);const sel=$('projectSelect');if(sel){if(isOpen&&[...sel.options].some(o=>o.value===String(openAtt.PROJECT_ID))){sel.value=String(openAtt.PROJECT_ID);sel.disabled=true}else{if(prevSel&&[...sel.options].some(o=>o.value===prevSel))sel.value=prevSel;sel.onchange=()=>{projectTouched=true;sel.classList.remove('auto-picked')};if(!projectTouched)selectNearestProject()}}if(prevName&&$('otherProjectName'))$('otherProjectName').value=prevName;renderAttendanceShiftState(custom);gpsWatch();renderGpsLine();if(refresh&&navigator.onLine&&Date.now()-lastBootAt>15000)bootstrap().then(()=>{if(screen===target)renderAttendance(custom,false)}).catch(()=>{})}
