function renderAttendanceShiftState(isOther=false){const area=$('attendanceActionArea');if(!area)return;refreshAttendanceEligibility(false);const state=S.attendanceShift,sh=currentShift();if(!sh){area.innerHTML='<p class="helper">Chưa cấu hình ca làm phù hợp. Liên hệ Admin.</p>';return}const att=attendanceForShift(sh.SHIFT_ID,sh.SHIFT_WORK_DATE||localDate()),open=!!(att&&att.CHECKIN_TIME&&!att.CHECKOUT_TIME),done=!!(att&&(att.CHECKOUT_TIME||String(att.STATUS)==='APPROVED'&&!att.CHECKIN_TIME)),pending=!!(att&&(att._local||att._pendingCheckout));if(isDayShift(sh)){area.innerHTML='<p class="helper">Ca NGÀY do Admin ghi nhận; nhân viên chỉ chấm công theo ca SÁNG/CHIỀU/TỐI.</p>';return}if(done){area.innerHTML=`<div class="success-card"><div class="success-icon">✓</div><h2>CA ĐÃ HOÀN TẤT</h2><p>${pending?'Đã lưu RA CA trên máy – đang chờ đồng bộ.':String(att.STATUS)==='PENDING'?'Đã RA CA – chờ Admin duyệt.':'Ca này đã RA CA thành công.'}</p></div>`;return}if(open){area.innerHTML=`<div class="success-card compact"><h2>${pending?'ĐÃ LƯU VÀO CA':'VÀO CA THÀNH CÔNG'}</h2><p>${pending?'Đang chờ đồng bộ – vẫn có thể RA CA.':'Vào lúc '+esc(clockText(att.CHECKIN_TIME)||'')+'. Chúc bạn làm việc hiệu quả!'}</p><button class="btn red full attendance-btn" onclick="checkout()">RA CA</button></div>`;return}const eligible=state?state.eligible:false;area.innerHTML=`<button class="btn green full attendance-btn" ${eligible?'':'disabled'} onclick="${isOther?'checkinOther()':'checkin()'}">VÀO CA</button>`;const hint=$('shiftHint');if(hint)hint.textContent=state?.reason||''}
async function requestDayAttendance(){toast('Nhân viên không tự ghi nhận ca NGÀY. Vui lòng liên hệ Admin.');}
// ===== V11.0.4 GPS: warm cache + watch while on the attendance screen; never blocks a tap =====
const GPS_STATE_KEY='cl_gps_permission_state',GPS_DENIED_AT='cl_gps_denied_at',GPS_FIX_KEY='cl_gps_last_fix',GPS_ACC_SEND=150,GPS_MAX_AGE=120000;
const GPS={fix:null,watchId:null,state:LS.getItem(GPS_STATE_KEY)||'unknown',keepUntil:0,waiters:[],permWatched:false};
try{const f=JSON.parse(LS.getItem(GPS_FIX_KEY)||'null');if(f&&Date.now()-f.timestamp<GPS_MAX_AGE)GPS.fix=f}catch(_){}
function gpsDenied(){if(GPS.state!=='denied')return false;const at=Number(LS.getItem(GPS_DENIED_AT)||0);if(at&&Date.now()-at>6*3600000){GPS.state='unknown';LS.removeItem(GPS_STATE_KEY);return false}return true}
function gpsFresh(maxAge=GPS_MAX_AGE,maxAcc=GPS_ACC_SEND){const f=GPS.fix;return f&&Date.now()-f.timestamp<=maxAge&&f.accuracy<=maxAcc?f:null}
function gpsAccept(pos){const f={latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:Math.round(pos.coords.accuracy||9999),timestamp:Date.now()},old=GPS.fix;if(!old||f.accuracy<=old.accuracy||Date.now()-old.timestamp>20000)GPS.fix=f;GPS.state='granted';LS.setItem(GPS_STATE_KEY,'granted');LS.removeItem(GPS_DENIED_AT);try{LS.setItem(GPS_FIX_KEY,JSON.stringify(GPS.fix))}catch(_){}if(!projectTouched)updateNearestProject(GPS.fix);renderGpsLine();GPS.waiters.slice().forEach(w=>w())}
function gpsError(e){if(e&&e.code===1){GPS.state='denied';LS.setItem(GPS_STATE_KEY,'denied');LS.setItem(GPS_DENIED_AT,String(Date.now()));gpsStop()}renderGpsLine()}
async function gpsWatchPermission(){if(GPS.permWatched||!navigator.permissions||!navigator.permissions.query)return;GPS.permWatched=true;try{const st=await navigator.permissions.query({name:'geolocation'});const apply=()=>{if(st.state==='denied'){GPS.state='denied';LS.setItem(GPS_STATE_KEY,'denied')}else{if(GPS.state==='denied'){GPS.state=st.state;LS.removeItem(GPS_STATE_KEY);LS.removeItem(GPS_DENIED_AT);if(isAttendanceScreen())gpsWatch()}else if(st.state==='granted')GPS.state='granted'}renderGpsLine()};apply();st.onchange=apply}catch(_){}}
// Quick, low-power fix (cell/Wi-Fi, cached up to 5 min). Called on home so the fix is warm before the user opens CHẤM CÔNG.
function gpsBoot(){if(!navigator.geolocation||gpsDenied())return;gpsWatchPermission();navigator.geolocation.getCurrentPosition(gpsAccept,gpsError,{enableHighAccuracy:false,timeout:8000,maximumAge:300000})}
// Continuous high-accuracy watch, only while the attendance screen is open (or briefly after a tap).
function gpsWatch(keepMs=0){if(keepMs)GPS.keepUntil=Math.max(GPS.keepUntil,Date.now()+keepMs);if(!navigator.geolocation||gpsDenied()||GPS.watchId!==null)return;gpsBoot();GPS.watchId=navigator.geolocation.watchPosition(gpsAccept,gpsError,{enableHighAccuracy:true,timeout:30000,maximumAge:10000})}
